enum Phase { Draft, Published { version: u32 } }

struct Post { phase: Phase, text: String }

impl Post {
    fn publish(&mut self) {
        self.phase = match self.phase {
            Phase::Draft => Phase::Published { version: 1 },
            Phase::Published { version } => Phase::Published { version: version + 1 },
        };
    }
}

